// src/utils/format-tokens.ts
function formatTokens(count, format = {}, decimals = 1) {
  const kDecimals = effectiveDecimals(format, decimals);
  if (count >= 1e6 - 500 / 10 ** kDecimals)
    return `${renderMagnitude(count / 1e6, format, 1)}M`;
  if (count >= 1000)
    return `${renderMagnitude(count / 1000, format, decimals)}k`;
  return count.toString();
}

